let genCount = context.get("genCount_finale") || 0;

if (genCount < 200) {
    genCount++;
    context.set("genCount_finale", genCount);

    let random_id = Math.floor(Math.random() * 30001);
    let current_ts = Math.floor(Date.now() / 1000);

    // Payload
    msg.payload = {
        id: random_id,
        timestamp: current_ts
    };

    // Add extra info for the CSV
    msg.row_num = genCount;

    return msg;
}

return null;

const REMAINDER_NUM = 5218; 
const ID_PROCESS_LIMIT = 200; 

let count = context.get("counter") || 0;

if (count < ID_PROCESS_LIMIT) {
    count++;
    context.set("counter", count); 

    let incomingData = msg.payload;
    if (typeof incomingData === "string") {
        try {
            incomingData = JSON.parse(incomingData);
        } catch(e) {
            return [null, null];
        }
    }

    let sub_id = incomingData.id;
    let N = parseInt(sub_id, 10) % REMAINDER_NUM;

    // Payload for CSV
    let newMsg = {
        payload: {
            "No.": count,
            "ID": sub_id,
            "TIMESTAMP": incomingData.timestamp
        },
        sub_id: sub_id,
        N: N,
        timestamp: incomingData.timestamp
    };

    if (count === ID_PROCESS_LIMIT) {
        let fineMsg = { payload: "END_ELABORATION " };
        return [newMsg, fineMsg]; 
    }

    return [newMsg, null]; 
}

return [null, null];

let cmdStr = msg.payload.payload; 
let timestamp = msg.payload.timestamp;

if (cmdStr.includes("RMS Current") || cmdStr.includes("RMS Voltage") || cmdStr.includes("Active Power")) {

    // Pulizia della stringa per renderla un JSON valido
    let cleanStr = cmdStr.replace(/'/g, '"');
    let obj;
    try {
        obj = JSON.parse(cleanStr);
    } catch (e) { return null; }

    // Estrazione Sequence Number
    let seqNum = obj["Sequence Number"] || ""; 

    // Estrazione array (se non esistono, creiamo array vuoti invece di forzare valori)
    let attrs = Array.isArray(obj["Attribute"]) ? obj["Attribute"] : (obj["Attribute"] ? [obj["Attribute"]] : []);
    let stats = Array.isArray(obj["Status"]) ? obj["Status"] : (obj["Status"] ? [obj["Status"]] : []);
    let types = Array.isArray(obj["Data Type"]) ? obj["Data Type"] : (obj["Data Type"] ? [obj["Data Type"]] : []);

    let valPower = obj["Int16"] || "0";
    let valOthers = Array.isArray(obj["Uint16"]) ? obj["Uint16"] : (obj["Uint16"] ? [obj["Uint16"]] : []);

    let count = context.get("csv_row_count") || 1;
    let results = [];

    let uint16Index = 0; 

    // Ciclo principale: accoppiamento posizionale
    for (let i = 0; i < attrs.length; i++) {
        let attrFull = attrs[i];
        if (!attrFull || typeof attrFull !== "string") continue; 

        let val = "";

        if (attrFull.includes("Active Power")) {
            val = valPower;
        } 
        else if (attrFull.includes("RMS Current") || attrFull.includes("RMS Voltage")) {
            if (valOthers[uint16Index] !== undefined) {
                 val = String(valOthers[uint16Index]).split(" ")[0];
                 uint16Index++; 
            } else {
                 val = "0"; 
            }
        }

        // Procediamo solo se è uno degli attributi di interesse
        if (attrFull.includes("Active Power") || attrFull.includes("RMS Current") || attrFull.includes("RMS Voltage")) {

            // Prendiamo lo status ESATTAMENTE nella stessa posizione (i). Se non c'è, stringa vuota.
            let statStr = stats[i] !== undefined ? String(stats[i]) : "";
            let typeStr = types[i] !== undefined ? String(types[i]) : "";

            let line = {
                "No.": count,
                "Timestamp": timestamp,
                "Sequence Number": seqNum,
                "Attribute": attrFull.split(" (")[0].trim(),
                "Status": statStr.split(" (")[0].trim(),
                "Data Type": typeStr.split(" (")[0].trim(),
                "Data Value": val
            };
            results.push(line);
            count++;
        }
    }

    context.set("csv_row_count", count);

    if (results.length > 0) {
        msg.payload = results;
        return msg;
    }
}
return null;

let rawRow = msg.payload; 

if (typeof rawRow !== "object" || rawRow === null) return [null, null];

// 1. KEY NORMALISATION: We create a new object with the keys cleaned up
let row = {};
for (let key in rawRow) {
    row[key.trim()] = rawRow[key];
}

// 2. Now we can use clean keys
if (!row["Packet Number"]) return [null, null];

let packetNumber = parseInt(row["Packet Number"], 10);
let targetN = parseInt(msg.N, 10);

if (packetNumber !== targetN) return [null, null];

let packetType = row["Packet Type"] || "";
let commandStr = row["Command String"] || "";

// --- 1: ZBEE_ZCL ---
if (commandStr && commandStr.includes("Layer ZBEE_ZCL")) {
    let devName = row["Device Name ZigBee Source"] ? row["Device Name ZigBee Source"].trim() : "Unknown";
    let topicStr = "ZigBee/" + devName;

    let outMsg = {
        topic: topicStr,
        payload: {
            timestamp: Math.floor(Date.now() / 1000),
            id: msg.sub_id,
            "wpan.src": row["Source Address"],
            "wpan.dst": row["Destination Address"],
            "zbee.src": row["Source Address ZigBee"],
            "zbee.dst": row["Destination Address ZigBee"],
            topic: topicStr,
            payload: commandStr
        },
        N: msg.N,
        sub_id: msg.sub_id,
        timestamp: msg.timestamp 
    };
    return [outMsg, null]; 
}

// --- 2: LINK STATUS ---
else if (packetType && packetType.includes("Link Status")) {
    let linkMsg = {
        payload: commandStr,
        source: row["Source Address ZigBee"]
    };
    return [null, linkMsg]; 
}

return [null, null];

// Recover Routing table
let routingTable = global.get("routingTable") || {};

let src = msg.source;
let cmdStr = msg.payload;

// Clean the string to make it a real JSON
let cleanStr = cmdStr.replace(/'/g, '"').replace(/True/g, 'true').replace(/False/g, 'false');

try {
    let obj = JSON.parse(cleanStr);

    // Check for links in this message
    if (obj.Links && Array.isArray(obj.Links)) {

        if (!routingTable[src]) {
            routingTable[src] = {};
        }

        // Update costs for each destination
        for (let i = 0; i < obj.Links.length; i++) {
            let link = obj.Links[i];
            let dest = link.Address;
            let cost = link["Outgoing Cost"];

            // Save costs
            routingTable[src][dest] = cost;
        }

        // Save update table in the global memory
        global.set("routingTable", routingTable);
    }
} catch (e) {
    node.warn("Errore parsing Link Status: " + e.message);
}

// This node must not pass anything on; its sole purpose is to store data
return null;

let routingTable = global.get("routingTable");

// If the table is empty, STOP
if (!routingTable) return null;

let results = [];
let rowNum = 1;

// The table is structured as follows: { source: { dest1: cost, dest2: cost } }
// We need to convert it into an array of rows for the CSV
for (let src in routingTable) {
    let destinations = routingTable[src];
    for (let dest in destinations) {
        let cost = destinations[dest];

        let row = {
            "No.": rowNum,
            "Source": src,
            "Destination": dest,
            "Cost": cost
        };
        results.push(row);
        rowNum++;
    }
}

if (results.length > 0) {
    msg.payload = results;
    return msg;
}

return null;

// Create the row
let row = {
    "No.": msg.row_num,
    "ID": msg.payload.id,
    "TIMESTAMP": msg.payload.timestamp
};

// Substitute the payload for the CSV
msg.payload = row;
return msg;

// Let's retrieve the complete map saved  in memory
let table = global.get("routingTable");
if (!table) return null;

// Let's select the smallest source address
// Let's extract all the source addresses we have found
let allSources = Object.keys(table);

// if there is nothing, we stop
if (allSources.length === 0) return null;

// Let’s sort the addresses from smallest to largest.
// We’ll use parseInt(..., 16) to tell Node-RED to treat them as proper hexadecimal numbers!
allSources.sort((a, b) => parseInt(a, 16) - parseInt(b, 16));

// The first address in the sorted list is, mathematically, the smallest
let sourceMin = allSources[0];

let destinations = table[sourceMin];

if (!destinations) return null;

// Let's extract the destinations and sort them in alphanumeric order
// Let's extract the destinations and sort them as actual hexadecimal numbers!
let destKeys = Object.keys(destinations).sort((a, b) => parseInt(a, 16) - parseInt(b, 16));
let messages = [];

// Let’s prepare a package for each destination
for (let i = 0; i < destKeys.length; i++) {
    let dest = destKeys[i];
    let cost = destinations[dest];

    // Let's include the cost in the “payload”, which will then be sent
    messages.push({ payload: cost }); 
}

// When returning an array of messages, Node-RED will queue them one after the other
return [messages];

// Imposta il  topic
msg.topic = "Unified RMS Voltage";

// Recupera il timestamp originale (in secondi) dal CSV
// Node-RED ui_chart richiede che il timestamp sia in millisecondi
let originalTimestamp = parseInt(msg.payload.Timestamp, 10);
msg.timestamp = originalTimestamp * 1000;

// Estrai il valore da tracciare e sovrascrivi il payload (ui_chart legge msg.payload)
msg.payload = parseFloat(msg.payload["Data Value"]);

return msg;

